<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/db.php';
$badges=$conn->query('SELECT b.badge_id,b.badge_name,b.description,b.badge_icon,b.criteria,COUNT(ub.user_id) AS award_count FROM `BADGE` b LEFT JOIN `USER_BADGE` ub ON ub.badge_id=b.badge_id GROUP BY b.badge_id,b.badge_name,b.description,b.badge_icon,b.criteria ORDER BY b.badge_name')->fetch_all(MYSQLI_ASSOC);
$users=$conn->query("SELECT user_id,F_name,m_name,L_name FROM `USER` WHERE status='active' ORDER BY F_name,L_name")->fetch_all(MYSQLI_ASSOC);
$awards=$conn->query('SELECT ub.user_id,ub.badge_id,ub.earned_date,u.F_name,u.L_name,b.badge_name FROM `USER_BADGE` ub JOIN `USER` u ON u.user_id=ub.user_id JOIN `BADGE` b ON b.badge_id=ub.badge_id ORDER BY ub.earned_date DESC LIMIT 30')->fetch_all(MYSQLI_ASSOC);
$pageTitle='Badges';require __DIR__.'/../includes/header.php';
?>
<section class="py-4 py-lg-5"><div class="container"><div class="mb-4"><div class="eyebrow text-primary mb-1">Recognition system</div><h1 class="section-title h2">Badges</h1></div><div class="row g-4"><div class="col-lg-7"><div class="surface-card p-4 mb-4"><div class="d-flex justify-content-between"><h2 class="h5">Badge definitions</h2><button class="btn btn-sm btn-primary" data-bs-toggle="collapse" data-bs-target="#newBadge">New badge</button></div><form class="collapse mt-3" id="newBadge" method="post" action="<?=e(url('actions/save_badge.php'))?>"><?=csrf_field()?><div class="row g-2"><div class="col-md-6"><input class="form-control" name="badge_name" maxlength="120" placeholder="Badge name" required></div><div class="col-md-6"><input class="form-control" name="badge_icon" maxlength="255" placeholder="Bootstrap icon, e.g. bi-award"></div><div class="col-12"><textarea class="form-control" name="description" maxlength="1000" placeholder="Description"></textarea></div><div class="col-12"><textarea class="form-control" name="criteria" maxlength="1000" placeholder="Criteria using available SkillSwap data"></textarea></div><div class="col-12"><button class="btn btn-primary">Create badge</button></div></div></form><?php foreach($badges as $badge):?><div class="d-flex gap-3 py-3 border-bottom"><span class="feature-icon flex-shrink-0"><i class="bi <?=e($badge['badge_icon']?:'bi-award')?>"></i></span><div class="flex-grow-1"><div class="d-flex justify-content-between"><strong><?=e($badge['badge_name'])?></strong><span class="badge badge-soft"><?=(int)$badge['award_count']?> awards</span></div><div class="small text-secondary"><?=e($badge['description'])?></div><div class="small mt-1"><strong>Criteria:</strong> <?=e($badge['criteria']?:'Not specified')?></div></div></div><?php endforeach;?></div></div><div class="col-lg-5"><form class="surface-card p-4 mb-4" method="post" action="<?=e(url('actions/assign_badge.php'))?>"><h2 class="h5">Assign a badge</h2><?=csrf_field()?><div class="mb-3"><label class="form-label">Student</label><select class="form-select" name="user_id" required><option value="">Choose user</option><?php foreach($users as $user):?><option value="<?=(int)$user['user_id']?>"><?=e(full_name($user))?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Badge</label><select class="form-select" name="badge_id" required><option value="">Choose badge</option><?php foreach($badges as $badge):?><option value="<?=(int)$badge['badge_id']?>"><?=e($badge['badge_name'])?></option><?php endforeach;?></select></div><button class="btn btn-primary w-100">Assign badge</button></form><div class="surface-card p-4"><h2 class="h5">Recent awards</h2><?php if(!$awards):?><p class="text-secondary small">No badge awards yet.</p><?php endif;?><?php foreach($awards as $award):?><div class="py-2 border-bottom"><strong><?=e(trim($award['F_name'].' '.$award['L_name']))?></strong><div class="small text-secondary"><?=e($award['badge_name'])?> - <?=e(date('M j, Y',strtotime($award['earned_date'])))?></div></div><?php endforeach;?></div></div></div></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
